    assert_eq!((status, code(&reply)), (404, "not_pinned"), "{reply}");
    assert!(
        port.host.state().written.is_empty(),
        "nothing reached a pane"
    );
    assert_eq!(
        port.app
            .core()
            .session(RecordId(uuid::Uuid::parse_str(&session).unwrap()))
            .unwrap()
            .notes,
        ""
    );
}

